struct Account { balance: Int }

enum Op {
    Deposit { amount: Int },
    Withdraw { amount: Int }
}

fn apply(in acc: Account, in op: Op) -> Account {
    match op {
        Op::Deposit { amount } => Account { balance: acc.balance + amount },
        Op::Withdraw { amount } => if acc.balance >= amount {
            Account { balance: acc.balance - amount }
        } else {
            acc
        }
    }
}

