module main;

pub fn int_sqrt(take n: Int) -> Int {
    var low = 0;
    var high = n;
    var candidate = 0;

    while low <= high {
        var mid = (low + high) / 2;
        var square = mid * mid;

        if square <= n {
            candidate = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    candidate
}

