pub fn rle(in s: Str) -> String {
    if std::str::len(s) == 0 {
        return std::string::empty();
    }

    var result = std::string::empty();
    var current_byte = std::str::byte_at(s, 0);
    var count = 1;
    var len = std::str::len(s);

    for i in 1..len {
        var next_byte = std::str::byte_at(s, i);
        if next_byte == current_byte {
            count += 1;
        } else {
            std::string::push_byte(result, current_byte);
            std::string::push_int(result, count);
            current_byte = next_byte;
            count = 1;
        }
    }

    std::string::push_byte(result, current_byte);
    std::string::push_int(result, count);

    return result;
}

