    var current = n;
    while current > 0 {
        var bit = current % 2;
        current = current / 2;
        s = std::string::append(s, if bit == 0 { "0" } else { "1" });
    }
    var len = std::string::len(s);
    var reversed = std::string::empty();
    for i in 0..len {
        var char = s.slice(len - 1 - i, len - i);
        reversed = std::string::append(reversed, char);
